style.css:
@-moz-document domain("youtube.com") {
:root {
    color-scheme: light dark;
  }

  /* Base search bar styling */
  .ytSearchboxComponentInputBox {
    background-color: light-dark(rgba(0, 0, 0, 0.05), rgba(255, 255, 255, 0.1));
    border: 1px solid #ff8800; /* Combined border properties */
    backdrop-filter: blur(0px);
    border-radius: 40px;
    padding-left: 15px !important;
    margin-right: 10px;
    transition: all 0.3s ease;
    color: light-dark(#000000, #ffffff);
    position: relative;
    box-shadow: none;
  }

  /* Hides icons inside the box when focused */
  .ytSearchboxComponentInputBox:focus-within svg,
  .ytSearchboxComponentInputBox:focus-within img,
  .ytSearchboxComponentInputBox:focus-within .ytSearchboxComponentSearchIcon,
  .ytSearchboxComponentInputBox:focus-within::before {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
  }

  /* The Search Button */
  .ytSearchboxComponentSearchButton {
    background-color: #315f84;
    border: none;
    border-radius: 40px;
    padding: 0 16px;
    min-width: 60px;
    transition: all 0.2s ease;
    color: light-dark(#000000, #ffffff);
    cursor: pointer;
  }

  /* Interaction Effects */
  .ytSearchboxComponentInputBox:hover {
    border-color: #ff8800;
  }

  .ytSearchboxComponentSearchButton:hover {
    background-color: #ff8800 !important;
    color: #ffffff !important;
  }
}
